-- Creates the brand rows that were missing entirely (Kevin.Murphy, Color Wow,
-- Aveda, Davines, Living Proof only had their logo_url updated in earlier
-- migrations, but the brand rows themselves never existed, so those updates
-- silently matched nothing). Safe to re-run: skips any brand that already exists.

insert into brands (name, logo_url)
select 'Kevin.Murphy', 'data:image/png;base64,'
where not exists (select 1 from brands where name = 'Kevin.Murphy');

insert into brands (name, logo_url)
select 'Color Wow', 'data:image/png;base64,'
where not exists (select 1 from brands where name = 'Color Wow');

insert into brands (name, logo_url)
select 'Aveda', 'data:image/png;base64,'
where not exists (select 1 from brands where name = 'Aveda');

insert into brands (name, logo_url)
select 'Davines', 'data:image/png;base64,'
where not exists (select 1 from brands where name = 'Davines');

insert into brands (name, logo_url)
select 'Living Proof', 'data:image/png;base64,'
where not exists (select 1 from brands where name = 'Living Proof');
